import{_ as o,o as e,c as r,a2 as l}from"./chunks/framework.Bx7X8BVG.js";const p=JSON.parse('{"title":"获取 Cloudflare 凭据","description":"3 步拿到 Account ID 与 API Token，只给 Cloudflare Tunnel 和 DNS 两条权限","frontmatter":{"title":"获取 Cloudflare 凭据","description":"3 步拿到 Account ID 与 API Token，只给 Cloudflare Tunnel 和 DNS 两条权限"},"headers":[],"relativePath":"get-credentials.md","filePath":"get-credentials.md","lastUpdated":1790778157000}'),a={name:"get-credentials.md"};function n(d,t,s,i,c,u){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="获取-cloudflare-account-id-与-api-token-3-步-1-分钟" tabindex="-1">获取 Cloudflare Account ID 与 API Token（3 步，1 分钟） <a class="header-anchor" href="#获取-cloudflare-account-id-与-api-token-3-步-1-分钟" aria-label="Permalink to &quot;获取 Cloudflare Account ID 与 API Token（3 步，1 分钟）&quot;">​</a></h1><p>面板只需要两样东西：<strong>Account ID</strong>（账号编号）和 <strong>API Token</strong>（带隧道权限的令牌）。照着下面点一遍就行，不需要看懂 Cloudflare 的其他功能。</p><blockquote><p>前提：你已经有一个托管在 Cloudflare 上的域名（域名在 Cloudflare 后台显示为「活动」状态）。</p></blockquote><hr><h2 id="第-1-步-复制-account-id" tabindex="-1">第 1 步：复制 Account ID <a class="header-anchor" href="#第-1-步-复制-account-id" aria-label="Permalink to &quot;第 1 步：复制 Account ID&quot;">​</a></h2><ol><li>登录 <a href="https://dash.cloudflare.com" target="_blank" rel="noreferrer">https://dash.cloudflare.com</a></li><li>随便进入任意一个域名的管理页（或直接在<strong>首页</strong>）</li><li><strong>右侧栏</strong>找到「<strong>账户 ID / Account ID</strong>」，点旁边的复制按钮</li></ol><p>它是一串 32 位字符，形如 <code>a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6</code> —— 这就是 Account ID。</p><blockquote><p>找不到？也可以打开 <a href="https://dash.cloudflare.com/?to=/:account/workers" target="_blank" rel="noreferrer">https://dash.cloudflare.com/?to=/:account/workers</a> ，右侧栏同样能看到「账户 ID」。</p></blockquote><h2 id="第-2-步-创建一个只带-tunnel-dns-权限的令牌" tabindex="-1">第 2 步：创建一个只带 Tunnel + DNS 权限的令牌 <a class="header-anchor" href="#第-2-步-创建一个只带-tunnel-dns-权限的令牌" aria-label="Permalink to &quot;第 2 步：创建一个只带 Tunnel + DNS 权限的令牌&quot;">​</a></h2><ol><li><p>打开 <a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">https://dash.cloudflare.com/profile/api-tokens</a></p></li><li><p>点「<strong>创建令牌 / Create Token</strong>」</p></li><li><p>拉到页面最下面，选「<strong>创建自定义令牌 / Create Custom Token</strong>」的「开始使用」</p></li><li><p>按下面填，<strong>只加这两条权限</strong>（其他都留空）。每条权限 = 三个下拉框：<strong>① 权限类型 → ② 具体权限 → ③ 级别</strong>，「编辑」就是第三个下拉框「级别」里的选项（英文界面叫 <strong>Edit</strong>）：</p><table tabindex="0"><thead><tr><th>权限类型</th><th>权限</th><th>级别</th></tr></thead><tbody><tr><td>账户 / Account</td><td><strong>Cloudflare Tunnel</strong></td><td><strong>编辑 / Edit</strong></td></tr><tr><td>区域 / Zone</td><td><strong>DNS</strong></td><td><strong>编辑 / Edit</strong></td></tr></tbody></table></li><li><p>往下「账户资源」选你的账户，「区域资源」选你要用的那个域名（也可以先选「所有区域」）</p></li><li><p>点「继续以显示摘要」→「<strong>创建令牌</strong>」</p></li><li><p><strong>立刻复制这串令牌</strong>（形如 <code>xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx</code>，只显示这一次，关掉就再也看不到了）</p></li></ol><blockquote><p>⚠️ 权限别多给：只给这两条就够了。不要用「Global API Key」（账户全局密钥，权限过大）。 💡 找不到「DNS」？注意是 <strong>DNS</strong>（区域级），不是「DNS 设置 / DNS Settings」。</p></blockquote><h2 id="第-3-步-填进面板" tabindex="-1">第 3 步：填进面板 <a class="header-anchor" href="#第-3-步-填进面板" aria-label="Permalink to &quot;第 3 步：填进面板&quot;">​</a></h2><ol><li>打开面板 → 左侧「<strong>⚙️ 系统配置</strong>」</li><li>「Cloudflare 账号」两个框分别粘贴 <strong>Account ID</strong> 和 <strong>API Token</strong></li><li>点「<strong>测试配置</strong>」→ 显示「✅ 测试通过：凭据有效」</li><li>点「<strong>保存配置</strong>」完成</li></ol><p>之后就可以去「Tunnel 列表」新建隧道了。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>提示 Invalid API Token / 认证失败</strong></p><ul><li>令牌复制不完整（前后带了空格）→ 重新复制一次</li><li>权限没给对：必须是「账户 · Cloudflare Tunnel · 编辑」+「区域 · DNS · 编辑」</li><li>区域资源没包含你要用的域名</li></ul><p><strong>提示找不到账户 / 无法创建隧道</strong></p><ul><li>Account ID 填错了（复制时多带了字符）</li><li>令牌的「账户资源」没选对账户</li></ul><p><strong>令牌泄露了怎么办</strong></p><ul><li>回到 <a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">https://dash.cloudflare.com/profile/api-tokens</a> ，把该令牌「删除」或「回滚」，重新生成一个填进面板即可。</li></ul><p><strong>凭据存在哪</strong></p><ul><li>只保存在你自己服务器的 <code>data/</code> 目录里，项目不含任何上报逻辑，不会外传。</li></ul><hr><h2 id="一键跳转" tabindex="-1">一键跳转 <a class="header-anchor" href="#一键跳转" aria-label="Permalink to &quot;一键跳转&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>地址</th></tr></thead><tbody><tr><td>API 令牌管理（创建/删除令牌）</td><td><a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">https://dash.cloudflare.com/profile/api-tokens</a></td></tr><tr><td>域名列表（查看账户 ID 也可在这里右侧栏）</td><td><a href="https://dash.cloudflare.com" target="_blank" rel="noreferrer">https://dash.cloudflare.com</a></td></tr></tbody></table>',27)])])}const g=o(a,[["render",n]]);export{p as __pageData,g as default};
